export function getIndustry(id) {
  return INDUSTRY_DECKS[id] || null;
}

export const INDUSTRY_LIST = INDUSTRY_ORDER.map((id) => {
  const d = INDUSTRY_DECKS[id];
  const slides = d.sections.reduce((n, s) => n + s.slides.length, 0);
  return { id, name: d.name, image: d.image, sections: d.sections.length, slides };
});
